select account_id, account_nickname, account_email, account_birth, account_contact, account_post, account_address1, account_address2, account_join, account_login, account_change, account_level, account_point, account_block from account
and account_id = #{accountId}
and account_nickname = #{accountNickname}
and account_contact = #{accountContact}
and instr(account_email, #{accountEmail}) > 0
and ( instr(account_post, #{accountAddress}) > 0 or instr(account_address1, #{accountAddress}) > 0 or instr(account_address2, #{accountAddress}) > 0 )
and to_timestamp(account_birth, 'yyyy-mm-dd') between to_timestamp(#{accountBirthBegin}, 'yyyy-mm-dd') and to_timestamp(#{accountBirthEnd}, 'yyyy-mm-dd')
and to_timestamp(account_birth, 'yyyy-mm-dd') >= to_timestamp(#{accountBirthBegin}, 'yyyy-mm-dd')
and to_timestamp(account_birth, 'yyyy-mm-dd') <= to_timestamp(#{accountBirthEnd}, 'yyyy-mm-dd')
and account_join between to_timestamp( #{accountJoinBegin} || ' ' || '00:00:00.000', 'yyyy-mm-dd hh24:mi:ss.ff3' ) and to_timestamp( #{accountJoinEnd} || ' ' || '23:59:59.999', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_join >= to_timestamp( #{accountJoinBegin} || ' ' || '00:00:00.000', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_join <= to_timestamp( #{accountJoinEnd} || ' ' || '23:59:59.999', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_login between to_timestamp( #{accountLoginBegin} || ' ' || '00:00:00.000', 'yyyy-mm-dd hh24:mi:ss.ff3' ) and to_timestamp( #{accountLoginEnd} || ' ' || '23:59:59.999', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_login >= to_timestamp( #{accountLoginBegin} || ' ' || '00:00:00.000', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_login <= to_timestamp( #{accountLoginEnd} || ' ' || '23:59:59.999', 'yyyy-mm-dd hh24:mi:ss.ff3' )
and account_level in (
#{accountLevel}
)
and account_block = #{accountBlock}
and account_point between #{accountPointMin} and #{accountPointMax}
and account_point >= #{accountPointMin}
and account_point <= #{accountPointMax}
select * from ( select * from temp_list
where rn > (
select rn from temp_list where account_id = #{lastAccountId} )
)
where rownum <= #{size}

